import React, {useEffect,useState} from 'react';import{createRoot}from'react-dom/client';
import{useChatOutbox}from'../../src/features/chat/useChatOutbox';import{chatApi}from'../../src/features/chat/api';import{VideoNoteBubble}from'../../src/features/chat/VideoNoteBubble';import type{Message}from'../../src/features/chat/types';
function Fixture(){const[rows,setRows]=useState<Message[]>([]),[error,setError]=useState('');const outbox=useChatOutbox('video-owner','10000000-0000-4000-8000-000000000081',{onAccepted:m=>setRows(old=>[...old.filter(x=>x.id!==m.id),m])});useEffect(()=>{void chatApi<{items:Message[]}>('/conversations/10000000-0000-4000-8000-000000000081/messages').then(r=>setRows(r.items));},[]);return <main><input aria-label="Видеофайл" type="file" accept="video/mp4" onChange={e=>{const file=e.target.files?.[0];e.target.value='';if(file)void outbox.enqueue({draft:{clientId:crypto.randomUUID(),kind:'video_note'},files:[{key:crypto.randomUUID(),file,kind:'video_note',duration:2}]}).catch(e=>setError(e.message));}}/>{error&&<p role="alert">{error}</p>}{outbox.pending.map(item=><div key={item.clientId} data-outbox-state={item.state}><VideoNoteBubble file={item.message.attachments[0]}/><span>{item.progress}</span>{item.state==='failed'&&<button onClick={()=>void outbox.retry(item.clientId)}>Повторить</button>}<button onClick={()=>void outbox.discard(item.clientId)}>Отменить загрузку</button></div>)}{rows.map(m=><div data-message-id={m.id} key={m.id}><VideoNoteBubble file={m.attachments[0]}/></div>)}</main>;}createRoot(document.getElementById('root')!).render(<React.StrictMode><Fixture/></React.StrictMode>);
